 \label{thm:worst_case_3M}
Consider the Best-of-three on  $G(2n,p,q)$ such that $p$ and $q$ are positive constants.
If $\frac{q}{p}>\frac{1}{7}$, then $G(2n,p,q)$ w.h.p.~satisfies the following property:

There exist two positive constants $C,C'>0$ such that 
\begin{align*}
\forall A\subseteq V\, :\, \mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A)\leq C\log n \right] \geq 1-O\left(n^{-C'}\right).
\end{align*}

 \label{thm:worst_case_2C}
Consider the Best-of-two on $G(2n,p,q)$ such that $p$ and $q$ are positive constants.
If $\frac{q}{p}>\sqrt{5}-2$, then $G(2n,p,q)$ w.h.p.~satisfies the following property:

There exist two positive constants $C,C'>0$ such that 
\begin{align*}
\forall A\subseteq V\, :\, \mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A)\leq C\log n \right] \geq 1-O\left(n^{-C'}\right).
\end{align*}

Let $G=(V,E)$ be a graph where each vertex holds an opinion from~$\{1,2\}$.
Let 
\begin{align*}
f^{\mathrm{Bo3}}(x)\mathrel{\mathop:}= \binom{3}{3}x^3+\binom{3}{2}x^2(1-x)=3x^2-2x^3.
\end{align*}
For the set $A$ of vertices holding opinion $1$,
let $A'$ denote the set of vertices that hold opinion $1$ after an update.
In the Best-of-three, $A'= \{v\in V: X_v=1\}$ where $(X_v)_{v\in V}$ are independent binary random variables satisfying 
\begin{align*}
\mathop{\mathbf{Pr}}[X_v=1]=
f^{\mathrm{Bo3}}\left(\frac{\deg_A(v)}{\deg(v)}\right).
\end{align*}

For a given function $f:[0,1]\to [0,1]$, we say $G(2n,p,q)$ is $f$-good if $G(2n,p,q)$ satisfies the following properties.
\begin{enumerate}[label={\rm (P\arabic*)}]
\setlength{\itemsep}{-1.8pt}
\item It is connected and non-bipartite. \label{pro:connectednonbipartite}
\item A positive constant $C_1$ exists such that, for all $A, S\subseteq V$ and $i\in\{1,2\}$, 
\begin{align*}
\left| \sum_{v\in S\cap V_i}f\left(\frac{\deg_A(v)}{\deg(v)}\right) - |S\cap V_i|f\left( \frac{|A_i|p+|A_{3-i}|q}{n(p+q)} \right) \right| \leq  C_1\sqrt{\frac{n}{p}}. 
\end{align*}
\label{pro:gomiN}
\item A positive constant $C_2$ exists such that, for all $A\subseteq V$, $S\in\{A, V\setminus A, V\}$ and $i\in\{1,2\}$, 
\begin{align*}
\sum_{v\in S\cap V_i}f\left(\frac{\deg_A(v)}{\deg(v)}\right) \leq 
|S\cap V_i|f\left( \frac{|A_i|p+|A_{3-i}|q}{n(p+q)} \right) + C_2|A|\sqrt{\frac{\log n}{np}}.
\end{align*}
\label{pro:gomiA}
\end{enumerate}

\label{thm:fgood}
Suppose that $f:[0,1]\to [0,1]$ is a polynomial function with constant degree, $p=\omega(\log n/n)$ and $q\geq \log n/n^2$. 
Then $G(2n,p,q)$ is $f$-good w.h.p.

\begin{align*}
W(S;A,B,C) &= W(V;V,V,V) - W(V;V,V,V\setminus C) - W(V;V,V\setminus B,C) \\
 & \ \ \ - W(V;V\setminus A,B,C)-W(V\setminus S;A,B,C).
\end{align*}

Equation \cref{eq:goodalphai} leads us to the dynamical system $H$, where we define $H:\mathbb{R}^2\to \mathbb{R}^2$ as
\begin{align}
H:\mathbf{a} \mapsto (H_1(\mathbf{a}),H_2(\mathbf{a})), \label{eqn:H_def}
\end{align}
and $H_i(a_1,a_2)\mathrel{\mathop:}= f^{\mathrm{Bo3}}\left(\frac{a_i+ra_{3-i}}{1+r}\right)$.

 \label{thm:approximation_vectorfield}
Consider the Best-of-three on an $f^{\mathrm{Bo3}}$-good $G(2n,p,q)$, starting with the vertex set $A^{(0)}\subseteq V$ holding opinion $1$.

Let $({\boldsymbol \alpha}^{(t)})_{t=0}^{\infty}$ be a stochastic process given by ${\boldsymbol \alpha}^{(t)}=(\alpha^{(t)}_1,\alpha^{(t)}_2)$ and $\alpha^{(t)}_i=|A^{(t)}\cap V_i|/n$.

Let $H$ be the mapping \cref{eqn:H_def} and define $(\mathbf{a}^{(t)})_{t=0}^\infty$ as 
\begin{align}
\label{eqn:veca_def}
\begin{cases}
\mathbf{a}^{(0)}={\boldsymbol \alpha}^{(0)},\\
\mathbf{a}^{(t+1)}=H(\mathbf{a}^{(t)}).
\end{cases}
\end{align}
Then there exists a positive constant $C>0$ such that
\begin{align*}
\forall 0\leq t\leq n^{o(1)},\forall A^{(0)}\subseteq V\,:\,\mathop{\mathbf{Pr}}\left[\|{\boldsymbol \alpha}^{(t)}-\mathbf{a}^{(t)}\|_\infty \leq C^t \left(\frac{1}{\sqrt{np}}+\sqrt{\frac{\log n}{n}}\right)\right] \geq 1-n^{-\Omega(1)}.
\end{align*}

\label{prop:3Mvectorfield}
For any sequence $(\mathbf{d}^{(t)})_{t=0}^\infty$, $\lim_{t\to\infty} \absp{\mathbf{d}^{(t)}}=\mathbf{d}^*_i$ for some $i\in\{1,2,3,4\}$.
In addition, if $u<\frac{3}{4}$ and a positive constant $\kappa>0$ exists such that the initial point $\mathbf{d}^{(0)}=(d^{(0)}_1,d^{(0)}_2)\in S$ satisfies $|d^{(0)}_2|>\kappa$, then $\lim_{t\to\infty} \absp{\mathbf{d}^{(t)}} =\mathbf{d}^*_4$.

 \label{prop:sink_3M}
Consider the Best-of-three on an $f^{\mathrm{Bo3}}$-good $G(2n,p,q)$ such that $r=q/p<1/7$ is a constant.
Then there exists a positive constant $\epsilon=\epsilon(r)$ satisfying
\begin{align*}
\mathop{\mathbf{Pr}}\left[\absp{{\boldsymbol \delta'}}\not\in B(\mathbf{d}_2^*,\epsilon) \,\middle|\, \absp{{\boldsymbol \delta}}\in B(\mathbf{d}_2^*,\epsilon)\right] \leq \exp(-\Omega(n)).
\end{align*}

In particular, 


$T_{\mathrm{cons}}(A) = \exp(\Omega(n))$ w.h.p.~for any $A$ satisfying $\absp{{\boldsymbol \delta}} \in B(\mathbf{d}_2^*,\epsilon)$.

 \label{prop:fastconsensus_3M}
Consider the Best-of-three on an $f^{\mathrm{Bo3}}$-good $G(2n,p,q)$ such that $r=q/p$ is a constant.
Then, there exists a universal constant $\epsilon=\epsilon(r)>0$ satisfying the following: $T_{\mathrm{cons}}(A) \leq O(\log\log n+\log n/\log (np))$ holds w.h.p.~for all $A\subseteq V$ with $\min\{|A|,2n-|A|\}\leq \epsilon n$.

 \label{prop:escape_3M}
Consider the Best-of-three on an $f^{\mathrm{Bo3}}$-good $G(2n,p,q)$ such that $p$ and $q$ are constants.

If $q/p>1/7$ and $|\delta_2^{(0)}|=o(1)$, then it holds w.h.p.~that $|\delta_2^{(\tau)}|>\kappa$ for some $\tau=O(\log n)$ and some constant $\kappa>0$.

