\mathop{\mathbf{Pr}}[X_v=1]&=
\begin{cases}
f_1\left(\frac{\deg_A(v)}{\deg(v)}\right) &(\textrm{$v\in A$, i.e.~$v$ has opinion $1$})\\
f_2\left(\frac{\deg_A(v)}{\deg(v)}\right) &(\textrm{$v\in V\setminus A$, i.e.~$v$ has opinion $2$})
\end{cases}.
\end{align*}

 \label{prop:sinkpoint}
Consider an $(f_1,f_2)$-polynomial voting process on an $f_1$-good and $f_2$-good $G(2n,p,q)$ such that $r=\frac{q}{p}$ is a constant.
Let $H$ be the induced dynamical system.
Then, for any sink point $\mathbf{a}^*$ and any sufficiently small $\epsilon=\omega(\sqrt{1/np})$,
\begin{align*}
\mathop{\mathbf{Pr}}\left[{\boldsymbol \alpha}'\not\in B(\mathbf{a}^*,\epsilon)\,\middle|\,{\boldsymbol \alpha}\in B(\mathbf{a}^*,\epsilon)\right]\leq \exp(-\Omega(\epsilon^2 n))
\end{align*}
holds.

In particular, let 
\begin{align*}
\tau:=\inf\left\{t\in\mathbb{N}:{\boldsymbol \alpha}^{(t)}\not\in B(\mathbf{a}^*,\epsilon)\right\}
\end{align*}
be a stopping time.
Then, $\tau\geq\exp(\Omega(\epsilon^2 n))$ holds w.h.p.~conditioned on ${\boldsymbol \alpha}^{(0)}\in B(\mathbf{a}^*,\epsilon)$ for any $\epsilon$ satisfying $\epsilon=\omega(\max\{1/\sqrt{np},\sqrt{\log n/n}\})$.

 \label{prop:fastconsensus_Jacob}
Consider an $(f_1,f_2)$-polynomial voting process on an $f_1$-good and $f_2$-good $G(2n,p,q)$ such that $\frac{p}{q}$ is a constant.
Suppose that the Jacobian matrix at the point ${\boldsymbol \alpha}=(0,0)$ is the all-zero matrix.

Then, there exists a constant $C_1,C_2,\delta>0$ such that
\begin{align*}
\mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A)\leq C_1\left(\log\log n+\frac{\log n}{\log np}\right)\right]\geq 1-n^{-C_2}
\end{align*}
for all $A\subseteq V$ satisfying $|A|\leq \delta n$.

 \label{prop:fastconsensus}
Consider a polynomial voting process on a graph $G$ of $n$ vertices.
Suppose that there exist absolute constants $C,\delta>0$ and a function $\epsilon=\epsilon(n)=o(1)$ such that
\begin{align*}
\mathbf{E}_{}[|A'|]\leq \frac{C|A|^{2}}{n}+\epsilon|A|
\end{align*}
holds for all $A\subseteq V$ satisfying $|A|\leq \delta n$.

Then, there exist positive constants $\delta',C',C''$ such that
\begin{align*}
\mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A)\leq C'\left(\log\log n+\frac{\log n}{\log\epsilon^{-1}}\right) \right]\geq 1-n^{-C''}
\end{align*}
holds for all $A\subseteq V$ satisfying $|A|\leq \delta'n$.

 \label{asm:escape_assumption0}
We consider an $(f_1,f_2)$-polynomial voting process on an $f_1$-good and $f_2$-good $G(2n,p,q)$ for constants $p\geq q\geq 0$.
Let $\mathbf{a}^*$ be a fixed point and $J$ be the corresponding Jacobian matrix satisfying
\begin{enumerate}[label={\rm (A\arabic*)}]
\item The eigenvectors $\mathbf{u}_1$ and $\mathbf{u}_2$ are linearly independent. \label{asm:asm1}
\item A positive constant $\epsilon_0$ exists such that $\mathop{\mathbf{Var}}[\alpha'_i\mid A]\geq \Omega(n^{-1})$ for all $i\in\{1,2\}$ and all $A\subseteq V$ of ${\boldsymbol \alpha}\in B\left(\mathbf{a}^*,\epsilon_0\right)$. \label{asm:asm2}
\item The matrix $J$ contains an eigenvalue $\lambda$ satisfying $|\lambda|>1$. \label{asm:asm3}
\end{enumerate}

 \label{asm:escape_assumption1}
In addition to \cref{asm:escape_assumption0}, we assume that there exists a positive constant $\epsilon^*$ satisfying the followings:
\begin{enumerate}[label={\rm (A\arabic*)}]
\setcounter{enumi}{3}
\item There exist two positive constants $\epsilon_1,C$ such that
\begin{align*}
|\mathbf{E}[\beta'_i\mid A]|\geq (1+\epsilon_1)|\beta_i|-\frac{C}{\sqrt{n}}
\end{align*}
holds for any $A\subseteq V$ of $\|{\boldsymbol \beta}\|\leq \epsilon^*$ and any $i\in[2]$ of $|\lambda_i|>1$. \label{asm:asm4}
\item For any $i\in [2]$ of $|\lambda_i|\leq 1$,
\begin{align*}
\mathop{\mathbf{Pr}}[|\beta'_i|\leq \epsilon^*\mid |\beta_i|\leq \epsilon^*] \geq 1-n^{-\Omega(1)}.
\end{align*}
\label{asm:asm5}
\end{enumerate}

\label{asm:escape_assumption2}
In addition to \cref{asm:escape_assumption0}, we assume the following:
\begin{enumerate}[label={\rm (A\arabic*)}]
\setcounter{enumi}{5}
\item The eigenvalues $\lambda_1,\lambda_2$ of $J$ satisfies $|\lambda_i|\neq 1$ for all $i\in[2]$. \label{asm:asm6}
\end{enumerate}

Suppose that $u<\frac{3}{4}$ (or equivalently, $r>\frac{1}{7}$) and that $p\geq q\geq 0$ are constants.
We prove that $T_{\mathrm{cons}}(A)=O(\log n)$ for any $A=A^{(0)}\subseteq V$.
Consider the stochastic process $({\boldsymbol \delta}^{(t)})_{t=0}^\infty$.
From \cref{prop:3Mvectorfield,prop:fastconsensus_3M}, it suffices to show that $|\delta_2^{(\tau)}|>\epsilon_1$ holds w.h.p.~for some constant $\epsilon_1>0$ and some $\tau=O(\log n)$.
To this end, we use \cref{prop:escape}.
From \cref{prop:3Mvectorfield}, we may assume
\begin{align}
{\boldsymbol \delta}^{(0)}\in \bigcup_{i\in\{1,2\}}B(\mathbf{d}^*_i,\epsilon_2) \label{eqn:initial_assumption}
\end{align}
for any constant $\epsilon_2>0$.
We check the condition~\ref{asm:asm2} of Assumption~\ref{asm:escape_assumption0}.
To this end, we show the following result:
\begin{theorem}[Concentration of the variance for the Best-of-three]  \label{thm:mainthm_Var}
Consider the Best-of-three on $f^{\mathrm{Bo3}}$-good $G(2n,p,q)$.
Then, two constants $C_1,C_2>0$ exist such that 

\begin{align*}
\forall A\subseteq V, \, \forall i\in\{1,2\}\,:\,
\left|\mathop{\mathbf{Var}}\left[|A'_i|\,\middle|\, A \right]
-
n\cdot g\left(\frac{|A_i|p+|A_{3-i}|q}{n(p+q)}\right)
\right| \leq C_2\sqrt{\frac{n}{p}},
\end{align*}
where $g(x)\mathrel{\mathop:}= f^{\mathrm{Bo3}}(x)(1-f^{\mathrm{Bo3}}(x))$.
\end{theorem}
\begin{proof}
That variance $\mathop{\mathbf{Var}}[|A'_i| \mid A]$ can be represented as
\begin{align*}
\mathop{\mathbf{Var}}[|A'_i| \mid A]
 = \sum_{v\in V_i} \mathop{\mathbf{Pr}}[v\in A'](1-\mathop{\mathbf{Pr}}[v\in A'])
 = \sum_{v\in V_i} f^{\mathrm{Bo3}}\left(\frac{\deg_A(v)}{\deg(v)}\right) \left(1-f^{\mathrm{Bo3}}\left(\frac{\deg_A(v)}{\deg(v)}\right)\right).
\end{align*}
Therefore, \cref{thm:mainthm_Var} immediately follows from property~\ref{pro:gomiN}.
\end{proof}
From \cref{thm:mainthm_Var}, a straightforward calculation leads to
\begin{align*}
\mathop{\mathbf{Var}}[\alpha'_i \mid A]
&= \frac{1}{n^2}\mathop{\mathbf{Var}}[|A'_i| \mid A] \\
&= \frac{(3z_i^2-2z_i^3)\bigl(1-(3z_i^2-2z_i^3)\bigr)}{n} \pm O\left(\frac{1}{\sqrt{n^3p}}\right) \\
&=\frac{z_i^2(3-2z_i)(1-z_i)^2(2z_i+1)}{n} \pm O\left(\frac{1}{\sqrt{n^3p}}\right),
\end{align*}
where $z_i=\frac{a_i+ra_{3-i}}{1+r}$.
If $|\delta_2|<1-\epsilon_3$ (or equivalently, $\epsilon_3<|a_1+a_2|<2-\epsilon_3$) for some constant $\epsilon_3>0$, we have $\mathop{\mathbf{Var}}[\alpha'_i]=\Omega(n^{-1})$.
Hence, the statement~\ref{asm:asm2} holds for every ${\boldsymbol \delta}$ satisfying ${\boldsymbol \delta} \in \bigcup_{i\in\{1,2\}}B(\mathbf{d}^*_i,\epsilon_2)$ with sufficiently small constant $\epsilon_2<1$ mentioned in \cref{eqn:initial_assumption}.


\paragraph*{The case of $u\neq\frac{2}{3}$.}
If $u\neq\frac{2}{3}$, then both $\mathbf{d}^*_1$ and $\mathbf{d}^*_2$ satisfy Assumption~\ref{asm:escape_assumption2}:
From \cref{eqn:Jacobian_3M}, both of these points satisfies the condition~\ref{asm:asm1} and~\ref{asm:asm3} of Assumption~\ref{asm:escape_assumption0}, and the condition~\ref{asm:asm6} of Assumption~\ref{asm:escape_assumption2} (here, we use $u\neq\frac{2}{3}$).

Suppose that $u<\frac{2}{3}$.
Then the fixed point $\mathbf{d}^*_2$ does not exist and thus we assume ${\boldsymbol \delta}^{(0)} \in B(\mathbf{d}^*_1,\epsilon_2)$.
From \cref{prop:escape}, we have $|\delta_2^{(\tau)}|>\epsilon_2$ for some $\tau=O(\log n)$ (note that ${\boldsymbol \beta}=(\beta_1,\beta_2)$ of \cref{eqn:betadef} is given by ${\boldsymbol \beta}={\boldsymbol \delta}$ and the eigenvalues satisfy $0\leq \lambda_1 < 1 < \lambda_2$).

Suppose that $u>\frac{2}{3}$.
Both eigenvalues of $J_1$ are strictly larger than $1$.
Hence, for $\mathbf{d}^*_1$, \cref{prop:escape} implies that either $|\delta_1^{(\tau)}|>\epsilon_2$ or $|\delta_2^{(\tau)}|>\epsilon_2$ holds for some $\tau=O(\log n)$ if ${\boldsymbol \delta}^{(0)} \in B(\mathbf{d}^*_1,\epsilon_2)$.
If the former holds with $|\delta_2^{(\tau)}|=o(1)$, then ${\boldsymbol \delta}^{(\tau+T)} \in B(\mathbf{d}^*_2,\epsilon_2)$ holds for some constant $T=T(\epsilon_2)$ since $d_1'>d_1$ holds whenever $0<d_1<\sqrt{\frac{3u-2}{u^3}}$ and $d_2=0$.
Note that, at the point $\mathbf{d}^*_2$, the Jacobian matrix $J_2$ has eigenvalues $\lambda_1,\lambda_2$ satisfying $0<\lambda_1<1<\lambda_2$.
Moreover, in look at \cref{eqn:betadef}, we have ${\boldsymbol \beta}={\boldsymbol \delta}-\mathbf{d}^*_2$.
Thus, \cref{prop:escape} yields that $|\delta_2^{(\tau')}|>\epsilon_2$ holds for some $\tau'=O(\log n)$ and for any ${\boldsymbol \delta}^{(0)} \in B(\mathbf{d}^*_2,\epsilon_2)$.

\paragraph*{The case of $u=\frac{2}{3}$.}
In this case, we have $\mathbf{d}^*_1=\mathbf{d}^*_2=(0,0)$.
We claim that this point satisfies \ref{asm:asm4} and \ref{asm:asm5} and then apply \cref{prop:escape}.

Let $\epsilon_2>0$ be sufficiently small constant mentioned in \cref{eqn:initial_assumption}.
The Jacobian matrix $J_1=J_2$ has eigenvalues $1$ and $\frac{3}{2}$.
Suppose that $\|{\boldsymbol \delta}^{(0)}\|_\infty \leq \epsilon_2$ for sufficiently small constant $\epsilon_2>0$.
Then, we have
\begin{align*}
|\mathbf{E}[\delta_2' \mid A]|&=\left|\frac{\delta_2}{2}(3-3(u\delta_1)^2-\delta_2^2)\right| \pm O(n^{-0.5})  \\
& \geq |\delta_2|\left(\frac{3}{2} - O_{\epsilon_2\to 0}(\epsilon_2)\right) - O(n^{-0.5})  \\
&\geq 1.49 |\delta_2| - O(n^{-0.5}).
\end{align*}
This verifies the assumption~\ref{asm:asm4}.
On the other hand, for any ${\boldsymbol \delta}$ of $|\delta_1|\leq\epsilon_2$, we have
\begin{align}
\left|\mathbf{E}[\delta_1' \mid A]\right|&=\left|\frac{u\delta_1}{2}\right|\left|3-(u\delta_1)^2-3\delta_2^2\right| \pm O(n^{-0.5}) \nonumber\\
&\leq |\delta_1|\left|1 - \frac{4}{27} \delta_1^2\right| + O(n^{-0.5}) \nonumber\\
&\leq |\delta_1|\left(1 - \frac{4}{27} \delta_1^2\right) + O(n^{-0.5}). \label{eqn:gamma1_exp_bound}
\end{align}
By applying the Hoeffding bound (\cref{lem:Hoeffding}) to the random variables $\delta_1=\alpha_1-\alpha_2$ and $\delta_2=\alpha_1+\alpha_2-\frac{1}{2}$, we obtain
\begin{align*}
\mathop{\mathbf{Pr}}\left[|\delta'_i-\mathbf{E}[\delta'_i]|\geq t\right] \leq \exp\left(-\Omega\left(nt^2\right)\right).
\end{align*}
In particular, letting $t=\sqrt{\frac{\log n}{n}}$, we have
\begin{align}
\delta'_i=\mathbf{E}[\delta'_i] \pm O\left(\sqrt{\frac{\log n}{n}}\right) \label{eqn:gamma_bound}
\end{align}
holds w.h.p.
We claim that 
\begin{align*}
\mathop{\mathbf{Pr}}\left[|\delta'_1|\leq\epsilon_2 \,\middle|\,|\delta_1|\leq\epsilon_2\right] \geq 1-n^{-\Omega(1)} 
\end{align*}
holds, which is equivalent to \ref{asm:asm5}.
From \cref{eqn:gamma1_exp_bound,eqn:gamma_bound}, if $|\delta_1|\leq\epsilon_2$, we have
\begin{align*}
|\delta'_1| \leq |\delta_1| - \frac{4}{27}|\delta_1|^3 + C\sqrt{\frac{\log n}{n}}
\end{align*}
for sufficiently large constant $C>0$ and large $n$.
If $|\delta_1|^3\geq \frac{27C}{4}\sqrt{\frac{\log n}{n}}$, we have $|\delta'_1|\leq |\delta_1|\leq \epsilon_2$ holds w.h.p.
If $|\delta_1|^3 < \frac{27C}{4}\sqrt{\frac{\log n}{n}}$, we have $|\delta'_1|=O\left(\sqrt{\frac{\log n}{n}}\right)\leq \epsilon_2$ holds w.h.p.

Thus, from \cref{prop:escape}, we have $|\delta^{(\tau)}_2|>\epsilon_2$ w.h.p.~for some $\tau=O(\log n)$.
This completes the proof of \cref{thm:worst_case_3M}.

\label{lem:WIdiscrepancy}
For a vertex set $V$ with $|V|=N$, let $(I_e)_{e\in \binom{V}{2}}$ be $\binom{N}{2}$ independent binary random variables. 
Let $p \mathrel{\mathop:}= \max_{e\in \binom{V}{2}}\mathbf{E}[I_e]$.
Suppose that $N p \geq 1$.
For $\ell+1$ vertex subsets $S_0, S_1, \ldots, S_\ell$, let
\begin{align*}
W(S_0;S_1,\ldots,S_\ell)&\mathrel{\mathop:}=\sum_{s\in S_0}\prod_{i\in[\ell]}\deg_{S_i}(s), 
\\
\hat{W}(S_0;S_1,\ldots,S_\ell)&\mathrel{\mathop:}= \sum_{s\in S_0}\prod_{i\in[\ell]}\mathbf{E}[\deg_{S_i}(s)]
\end{align*}
where $\deg_S(v)=\sum_{s\in S\setminus \{v\}}I_{\{v,s\}}$ for $S\subseteq V$ and $v\in V$.

Then two positive constants $C_1, C_2$ exist such that the following holds with probability $1-N^{-C_1}$: 
\begin{align*}
\forall S_0, S_1, \ldots, S_\ell: \bigl|W(S_0;S_1,\ldots,S_\ell)-\hat{W}(S_0;S_1,\ldots,S_\ell)\bigr| 
\leq C_2N (N p)^{\ell-1/2}.
\end{align*}

Let $f(x)=\sum_{j=0}^\ell c_jx^j$.
For notational convenience, 
let $x_v=\frac{\deg_A(v)}{\deg(v)}$, $\bar{x}_v=\frac{\mathbf{E}[\deg_A(v)]}{\mathbf{E}[\deg(v)]}$ and $\hat{x}=\frac{|A_{i}|p+|A_{3-i}|q}{n(p+q)}$.
Then from the triangle inequality, it holds that
\begin{align}
\left|\sum_{v\in S\cap V_i}\bigl(f(x_v)-f(\hat{x})\bigr)\right|

&\leq \left|\sum_{v\in S\cap V_i}\bigl(f(x_v)-f(\bar{x}_v)\bigr)\right|+\left|\sum_{v\in S\cap V_i}\bigl(f(\bar{x}_v)-f(\hat{x})\bigr)\right|.
\label{eq:trianglegomi}
\end{align}
For the second term of the right hand of \cref{eq:trianglegomi}, two positive constant $C_1, C_2$ exist such that
\begin{align*}
\left|\sum_{v\in S\cap V_i}\bigl(f(\bar{x}_v)-f(\hat{x})\bigr)\right|
\leq \sum_{v\in S\cap V_i}|f(\bar{x}_v)-f(\hat{x})|
\leq C_1\sum_{v\in S\cap V_i}|\bar{x}_v-\hat{x}|
\leq C_2\frac{|S\cap V_i|}{n} 
\leq C_2.
\end{align*}
The second inequality follows from the Lipschitz condition of $f$ (c.f.~\cref{sec:lipschitzcondition}).
The third inequality holds since $\mathbf{E}[\deg(v)]=(n-1)p+nq$ and $(|A_{i}|-1)p+|A_{3-i}|q \leq \mathbf{E}[\deg_A(v)]\leq |A_{i}|p+|A_{3-i}|q$ for any $v\in V_i$.

For the first term of the right hand of \cref{eq:trianglegomi}, since
\begin{align*}
\left(\frac{\deg_A(v)}{\deg(v)}\right)^j-\left(\frac{\mathbf{E}[\deg_A(v)]}{\mathbf{E}[\deg(v)]}\right)^j
&=\frac{\left(\mathbf{E}[\deg(v)]^j-\deg(v)^j\right)\left(\frac{\deg_A(v)}{\deg(v)}\right)^j+\left(\deg_A(v)^j-\mathbf{E}[\deg_A(v)]^j\right)}{\mathbf{E}[\deg(v)]^j}
\end{align*}
for any $j$ and $v\in V$, we have
\begin{align*}
\lefteqn{\left|\sum_{v\in S\cap V_i}\bigl(f(x_v)-f(\bar{x}_v)\bigr)\right|
=\left|\sum_{j=1}^{\ell}c_j \sum_{v\in S\cap V_i}\left((x_v)^j-(\bar{x}_v)^j\right)\right|}\\
&\leq \sum_{j=1}^\ell \frac{|c_j|}{((n-1)p)^j} \left(\left|\sum_{v\in S\cap V_i}\left(\mathbf{E}[\deg(v)]^{j}-\deg(v)^j\right)\left(x_v\right)^j \right|+\left| \sum_{v\in S\cap V_i}\left(\deg_A(v)^j-\mathbf{E}[\deg_A(v)]^j\right)\right|\right).

\end{align*}
Note that $\mathbf{E}[\deg(v)]=(n-1)p+nq\geq (n-1)p$ for any $v\in V$.
Since
\begin{align*}
\left|\sum_{v\in S\cap V_i}\left(\mathbf{E}[\deg(v)]^{j}-\deg(v)^j\right)\left(x_v\right)^j \right|
&\leq \max_{U\subseteq V}\left|\sum_{u\in U}\left(\mathbf{E}[\deg(u)]^{j}-\deg(u)^j\right)\right|\\
&=\max_{U\subseteq V}\left|W(U;\overbrace{V,\ldots,V}^{j})-\hat{W}(U;\overbrace{V,\ldots,V}^{j})\right|
\end{align*}
and $\sum_{v\in S\cap V_i}\left(\deg_A(v)^j-\mathbf{E}[\deg_A(v)]^j\right)=W(S\cap V_i;\overbrace{A,\ldots,A}^{j})-\hat{W}(S\cap V_i;\overbrace{A,\ldots,A}^{j})$, 
we obtain the claim from \cref{lem:WIdiscrepancy}.
Note that, for any $S\subseteq V$, $a\in \mathbb{R}^V$ and $x\in [0,1]^V$, $|\sum_{s\in S}a_sx_s|\leq \max_{U\subseteq V}|\sum_{u\in U}a_u|$ since 
$\sum_{s\in S:a_s\leq 0}a_s \leq \sum_{s\in S}a_sx_s\leq \sum_{s\in S:a_s\geq 0}a_s$.

\begin{align*}
\left|\sum_{v\in S\cap V_i}\bigl(f(\bar{x}_v)-f(\hat{x})\bigr)\right|
\leq \sum_{v\in S\cap V_i}|f(\bar{x}_v)-f(\hat{x})|
\leq C_1\sum_{v\in S\cap V_i}|\bar{x}_v-\hat{x}|
\leq C_2\frac{|S\cap V_i|}{n} 
\leq C_2.
\end{align*}

\label{lem:technique}
Let $V$ be a set of $|V|=N$ vertices
and fix $l+1$ subsets $S_0, S_1, \ldots, S_l\subseteq V$. 
For any $\mathbf{s}=(s_0,s_1,\ldots, s_l)\in S_0\times S_1\times \cdots \times S_l$, 
define 
\begin{align*}
U(\mathbf{s})&\mathrel{\mathop:}= \{s_i: i\in \{0\}\cup [l]\}.
\end{align*}
Consider $\sum_{\substack{\mathbf{s}\in \mathcal{S}}}p^{|\mathcal{F}(\mathbf{s})|}$, where 
$p\in [1/N,1]$, $\mathcal{S}\subseteq S_0\times S_1\times \cdots \times S_l$ and  
\begin{align*}
\mathcal{F}: S_0\times S_1\times \cdots \times S_l \to 2^{\binom{V}{2}}.
\end{align*}
Suppose that the following three conditions hold for any $\mathbf{s}\in \mathcal{S}$:  
(1) $|\mathcal{F}(\mathbf{s})|\leq k$, 
(2) $\mathcal{F}(\mathbf{s})\subseteq \binom{U(\mathbf{s})}{2}$ 
and 
(3) the graph $G(\mathbf{s})=\bigl(U(\mathbf{s}), \mathcal{F}(\mathbf{s})\bigr)$ is connected.
Let $L\subseteq \{0\}\cup [l]$ be the set of indices such that $S_i\cap S_j=\emptyset$ for any $i,j\in L$ $(i\neq j)$.
Then
\begin{align*}
\sum_{\substack{\mathbf{s}\in \mathcal{S}}}p^{|\mathcal{F}(\mathbf{s})|}\leq \mathcal{B}_{l+1}N (N p)^k\frac{\prod_{i\in L}|S_i|}{N ^{|L|}}
\end{align*}
where $\mathcal{B}_l$ denotes the $l$-th Bell number.

\label{lem:WEWdiscrepancy}
Suppose the same setting of \cref{lem:WIdiscrepancy}.

Then two positive constants $C_1, C_2$ exist such that the following holds with probability $1-N^{-C_1}$: 
\begin{align*}
\forall S_0, S_1, \ldots, S_\ell: 
\bigl|W(S_0;S_1,\ldots,S_\ell)-\mathbf{E}[W(S_0;S_1,\ldots,S_\ell)]\bigr|\leq  C_2 N(N p)^{\ell-1/2}.

\end{align*}

\begin{align*}
\forall S_0, S_1, \ldots, S_\ell: 
\bigl|W(S_0;S_1,\ldots,S_\ell)-\mathbf{E}[W(S_0;S_1,\ldots,S_\ell)]\bigr|\leq  C_2 N(N p)^{\ell-1/2}.

\end{align*}

For $\ell+1$ vertex subsets $S_0, S_1, \ldots, S_\ell$, let
\begin{align*}
\mathbf{S}&\mathrel{\mathop:}=\left\{(s_0,s_1,\ldots,s_\ell): s_0\in S_0, s_i \in S_i\setminus \{s_0\}\ \textrm{for every $i\in [\ell]$}\right\}
\end{align*}
and for any $\mathbf{s}=(s_0, s_1,\ldots, s_\ell)\in \prod_{i=0}^\ell S_i=S_0 \times S_1\times \cdots \times S_\ell$, let 
\begin{align*}
F(\mathbf{s})&\mathrel{\mathop:}= \bigl\{\{s_0,s_i\}: i\in [\ell] \bigr\}\setminus \{s_0\}. 
\end{align*}
For example, 

$F\bigl((a,b,a,c,d,b,f,a)\bigr)=\bigl\{\{a,b\},\{a,c\},\{a,d\},\{a,f\}\bigr\}$.

Then, 
\begin{align}
W(S_0;S_1,\ldots, S_\ell)
&=\sum_{s_0\in S_0}\prod_{i\in [\ell]}\left(\sum_{s_i\in S_i\setminus \{s_0\}}I_{\{s_0,s_i\}}\right)
=\sum_{\mathbf{s}\in \mathbf{S}}\prod_{i\in [\ell]} I_{\{s_0,s_i\}}
=\sum_{\mathbf{s}\in \mathbf{S}}\prod_{e\in F(\mathbf{s})} I_{e}.

\label{eq:WtoJ}
\end{align}





\

\noindent \textbf{Lower bound on $W$. } 
First, we claim the following:
Two positive constants $C_3, C_4$ exist such that
\begin{align}
\mathop{\mathbf{Pr}}\left[\forall S_0, S_1\ldots, S_\ell: W(S_0;S_1,\ldots, S_\ell)\geq \mathbf{E}[W(S_0;S_1,\ldots, S_\ell)]-C_4 N (N p)^{\ell-1/2}  \right]\geq 1-N^{-C_3}.
\label{claim:WEWlower}
\end{align}
To obtain \cref{claim:WEWlower}, we apply Janson's inequality (\cref{lem:Janson}) to \cref{eq:WtoJ}.
Then we have
\begin{align}
\lefteqn{\mathop{\mathbf{Pr}}\left[\exists S_0,S_1,\ldots, S_\ell: W(S_0;S_1,\ldots,S_\ell)\leq \mathbf{E}[W(S_0;S_1,\ldots,S_\ell)]-t\right]} \nonumber \\
&\leq \left(2^N\right)^{\ell+1}\exp\left(-\frac{t^2}{2\nabla(S_0;S_1,\ldots,S_\ell)}\right)
\leq \exp\left((\ell+1)N-\frac{t^2}{2\nabla(S_0;S_1,\ldots,S_\ell)}\right)
\label{eq:WJansonwithNabla}

\end{align}
where
\begin{align*}
\nabla(S_0;S_1,\ldots,S_\ell)
&= \sum_{\substack{\mathbf{s}\in \mathbf{S},\mathbf{s}'\in \mathbf{S}:\\F(\mathbf{s})\cap F(\mathbf{s}')\neq \emptyset}}
\mathbf{E}\left[\prod_{e\in F(\mathbf{s})} I_{e}\prod_{e'\in F(\mathbf{s}')} I_{e'}\right].
\end{align*}
Thus it suffices to show that
$
\nabla(S_0;S_1,\ldots,S_\ell)
= O(N (N p)^{2\ell-1})
$.
Since $\max_{e\in \binom{V}{2}}\mathbf{E}[J_e]=p$, it holds that
\begin{align}
\nabla(S_0;S_1,\ldots,S_\ell)
&=\sum_{\substack{\mathbf{s}\in \mathbf{S},\mathbf{s}'\in \mathbf{S}:\\F(\mathbf{s})\cap F(\mathbf{s}')\neq \emptyset}}
\mathbf{E}\left[\prod_{e\in F(\mathbf{s})} I_{e}\prod_{e'\in F(\mathbf{s}')} I_{e'}\right]
\leq \sum_{\substack{\mathbf{s}\in \mathbf{S},\mathbf{s}'\in \mathbf{S}:\\F(\mathbf{s})\cap F(\mathbf{s}')\neq \emptyset}}
p^{|F(\mathbf{s})\cup F(\mathbf{s}')|}. 
\label{eq:nablaupper1}
\end{align}
To bound \cref{eq:nablaupper1}, we apply \cref{lem:technique} which we will prove in \cref{sec:technique}.

Consider $2\ell+2$ vertex subsets $S'_0, S'_1, \ldots, S'_{2\ell+1}$ where $S'_i\mathrel{\mathop:}= S_{i\bmod (\ell+1)}$.
For any $i\in \{0\}\cup [2\ell+1]$, let 
\begin{align*}
\mathcal{S}&\mathrel{\mathop:}= \left\{ (s_0, s_1, \ldots, s_{2\ell+1})\in \mathbf{S}\times \mathbf{S} : F\bigl((s_0, \ldots, s_{\ell})\bigr)\cap F\bigl((s_{\ell+1},\ldots, s_{2\ell+1})\bigr)\neq \emptyset \right\}\subseteq \prod_{i=0}^{2\ell+1}S'_i, \\
\mathcal{F}(\mathbf{s})&\mathrel{\mathop:}= F\bigl((s_0, \ldots, s_{\ell})\bigr)\cup F\bigl((s_{\ell+1},\ldots, s_{2\ell+1})\bigr)\ \textrm{for any}\ \mathbf{s}=(s_0, s_1, \ldots, s_{2\ell+1})\in \prod_{i=0}^{2\ell+1}S'_i.
\end{align*}
Then for any $\mathbf{s}\in \mathcal{S}$, 
$G({\mathbf{s}})=\bigl(U({\mathbf{s}}), \mathcal{F}(\mathbf{s})\bigr)$ is a connected graph 
and $|\mathcal{F}(\mathbf{s})|\leq 2\ell-1$.
Thus, for any $i_* \in \{0\} \cup [\ell]$, \cref{lem:technique} with letting $l=2\ell+1,k=2\ell-1$ and $L=\{i_*\}$ yields
\begin{align}
\sum_{\substack{\mathbf{s}\in \mathbf{S},\mathbf{s}'\in \mathbf{S}:\\F(\mathbf{s})\cap F(\mathbf{s}')\neq \emptyset}}
p^{|F(\mathbf{s})\cup F(\mathbf{s}')|}
&=\sum_{\mathbf{s}\in \mathcal{S}}p^{|\mathcal{F}(\mathbf{s})|}
\leq \mathcal{B}_{2(\ell+1)}N(Np)^{2\ell-1}\frac{|S_{i_*}'|}{N}
=\mathcal{B}_{2(\ell+1)}|S_{i_*}|(N p)^{2\ell-1}.
\label{eq:nablaupper2}
\end{align}

Equations~\cref{eq:nablaupper1,eq:nablaupper2} imply the following statement:
For any $\ell+1$ vertex subsets $S_0, S_1, \ldots S_\ell$ and for any $i_*\in \{0\}\cup [\ell]$, 
\begin{align}
\nabla(S_0;S_1,\ldots,S_\ell)
&\leq \mathcal{B}_{2(\ell+1)}|S_{i_*}|(N p)^{2\ell-1}
\leq \mathcal{B}_{2(\ell+1)}N (N p)^{2\ell-1}.
\label{claim:nablaupper}
\end{align}
Thus by substituting $t=C_4 N(N p)^{\ell-1/2}$ with $C_4=\sqrt{2(\ell+1+C_3)\mathcal{B}_{2(\ell+1)}}$ to \cref{eq:WJansonwithNabla}, we obtain the claim \cref{claim:WEWlower}.

\

\noindent \textbf{Upper bound on $W$. }
To complete the proof of \cref{lem:WEWdiscrepancy}, we combine the claim \cref{claim:WEWlower} and  the following claim:
Two positive constants $C_5, C_6$ exist such that
\begin{align}
\mathop{\mathbf{Pr}}\left[\forall S_0, S_1\ldots, S_\ell: W(S_0;S_1,\ldots, S_\ell)\leq \mathbf{E}[W(S_0;S_1,\ldots, S_\ell)]+C_6 N (N p)^{\ell-1/2}  \right]\geq 1-N^{-C_5}.
\label{claim:WEWupper}
\end{align}
To show the claim, we consider the following expression of $W$.
For any $S_0, S_1, \ldots, S_\ell$, let 
$W_0\mathrel{\mathop:}= W(S_0;S_1,\ldots,S_\ell)$ and
let 
$W_i\mathrel{\mathop:}= W(\overbrace{V; V\ldots, V}^{i}, S_{i}, S_{i+1}, \ldots, S_{\ell})$ for each $i\in[\ell+1]$.
Since $W_{i+1}-W_{i}=W(\overbrace{V;V,\ldots,V}^{i},V\setminus S_{i}, S_{i+1}, \ldots, S_{\ell})$ for any $i\in \{0\}\cup [\ell+1]$
and $\sum_{i=0}^{\ell}(W_{i+1}-W_{i})=W_{\ell+1}-W_0$, we have
\begin{align}
\label{eq:WdlV}
W(S_0;S_1,\ldots,S_{\ell})&=W(\overbrace{V;V,\ldots,V}^{\ell+1})-\sum_{i=0}^{\ell}W(\overbrace{V;V,\ldots,V}^{i},V\setminus S_{i}, S_{i+1}, \ldots, S_{\ell}).
\end{align}
We can apply \cref{claim:WEWlower} for the second term of the right hand of \cref{eq:WdlV}. 

Now we try to get an upper bound on $W(\overbrace{V;V,\ldots,V}^{\ell+1})$. 
For the notational convenience, let $Y=W(\overbrace{V;V,\ldots,V}^{\ell+1})$.

Let $S_i=V$ for every $i\in \{0\}\cup [\ell]$ and let 
\begin{align*}
\mathcal{E}&\mathrel{\mathop:}= \left\{F(\mathbf{s}): \mathbf{s}\in \mathbf{S}\right\}.
\end{align*}
From \eqref{eq:WtoJ}, we have
\begin{align*}
Y
=\sum_{\mathbf{s}\in \mathbf{S}}\prod_{e\in F(\mathbf{s})}I_e
=\sum_{F\in \mathcal{E}} |\{\mathbf{s}\in \mathbf{S} : F(\mathbf{s})=F\}|\prod_{e\in F}I_e.
\end{align*}
Thus applying Kim-Vu inequality (\cref{lem:Kim-Vu}) to $Y$ yields
\begin{align}
\mathop{\mathbf{Pr}}\left[|Y-\mathbf{E}[Y]|\geq \sqrt{\ell! \max_{A\subseteq \binom{V}{2}}\mathbf{E}[Y_{A}]\max_{A\subseteq \binom{V}{2}:A\neq \emptyset}\mathbf{E}[Y_{A}]}(8\lambda)^\ell\right]\leq 2\exp(2+2(\ell-1)\log N-\lambda)
\label{eq:KimVutoY}
\end{align}
where
\begin{align*}
Y_{A}
&=\sum_{\substack{F\in \mathcal{E}:\\F\supseteq A}} |\{\mathbf{s}\in \mathbf{S}:  F(\mathbf{s})=F\}|\prod_{e\in F\setminus A}I_e
=\sum_{\substack{\mathbf{s}\in \mathbf{S}:\\ F(\mathbf{s}) \supseteq A}}\prod_{e\in F(\mathbf{s})\setminus A}I_e.
\end{align*}






Now, we give an upper bound on $\mathbf{E}[Y_{A}]$. 

Since $\max_{e\in \binom{V}{2}}\mathbf{E}[J_e]=p$,
it holds that
\begin{align*}
\mathbf{E}[Y_{A}]=\sum_{\substack{\mathbf{s}\in \mathbf{S}:\\ F(\mathbf{s}) \supseteq A}}\mathbf{E}\left[\prod_{e\in F(\mathbf{s})\setminus A}I_e\right]
\leq \sum_{\substack{\mathbf{s}\in \mathbf{S}:\\ F(\mathbf{s}) \supseteq A}}p^{|F(\mathbf{s})\setminus A|}
=\sum_{\substack{\mathbf{s}\in \mathbf{S}:\\ F(\mathbf{s}) \supseteq A}}p^{|F(\mathbf{s})|-|A|}.
\end{align*}

If $A=\emptyset$, 
a direct application of \cref{lem:technique} with letting $l=k=\ell$ and $L=\emptyset$ yields
\begin{align}
\mathbf{E}[Y_{A}]=\mathbf{E}[Y]
&\leq \sum_{\substack{\mathbf{s}\in \mathbf{S}}}p^{|F(\mathbf{s})|}


\leq \mathcal{B}_{\ell+1}N (N p)^{\ell}.
\label{eq:YAzero}
\end{align}
Note that $|F(\mathbf{s})|\leq \ell$ and $G({\mathbf{s}})=(U(\mathbf{s}),F(\mathbf{s}))$ is a connected graph for any $\mathbf{s}\in \mathbf{S}\subseteq \prod_{i=0}^\ell S_i$.

Now we consider the case $|A|=\kappa\geq 1$.
Let $V(A)$ be the set of vertices induced by the edge set $A\subseteq \binom{V}{2}$.
If $F(\mathbf{s})\supseteq A$ for some $\mathbf{s}\in \prod_{i=0}^\ell V$, the graph 
$G'=(V(A),A)$ is a star graph and hence $|V(A)|=|A|+1=\kappa+1$.
Let $V(A)=\{a_0, a_1, \ldots, a_{\kappa}\}$.
Now consider $(\ell+1)+(\kappa+1)$ vertex subsets $S'_0, S'_1, \ldots S'_{\ell+\kappa+1}$ where $S'_i=S_i$ for any $0\leq i\leq \ell$ and $S'_i=\{a_{i-(\ell+1)}\}$ for any $\ell+1\leq i\leq \ell+\kappa+1$.
Let
\begin{align*}
\mathcal{S}&\mathrel{\mathop:}= \left\{ (s_0, s_1, \ldots, s_{\ell+\kappa+1})\in \mathbf{S}\times \prod_{i=0}^{\kappa}\{a_i\}: F\bigl( (s_0,\ldots,s_\ell)\bigr)\supseteq A \right\}\subseteq \prod_{i=0}^{\ell+\kappa+1}S'_i,\\
\mathcal{F}(\mathbf{s})&\mathrel{\mathop:}= F\bigl((s_0,\ldots,s_\ell)\bigr) \ \textrm{for any}\ \mathbf{s}=(s_0, s_1, \ldots, s_{\ell+\kappa+1})\in \prod_{i=0}^{\ell+\kappa+1}S'_i.
\end{align*}
Note that, for any $\mathbf{s}\in \mathcal{S}$, 
the graph $G({\mathbf{s}})=\bigl(U({\mathbf{s}}), \mathcal{F}(\mathbf{s})\bigr)$ is connected and $|\mathcal{F}(\mathbf{s})|\leq \ell$.
Thus \cref{lem:technique} 
with letting $l=\ell+\kappa+1$, $k=\ell$ and $L=\{\ell+1, \ell+2, \ldots, \ell+\kappa+1\}$ (note that $a_i\neq a_j$ for any $i\neq j$ and $\prod_{i=\ell+1}^{\ell+\kappa+1}|S'_i|=\prod_{i=\ell+1}^{\ell+\kappa+1}|\{a_{i-(\ell+1)}\}|=1$)
yields
\begin{align}
\mathbf{E}[Y_{A}]
&\leq 
\sum_{\substack{\mathbf{s}\in \mathbf{S}:\\ F(\mathbf{s}) \supseteq A}}p^{|F(\mathbf{s})|-|A|}
=\frac{1}{p^{\kappa}}\sum_{\substack{\mathbf{s}\in \mathcal{S}}}p^{|\mathcal{F}(\mathbf{s})|}
\leq \frac{1}{p^{\kappa}} \mathcal{B}_{\ell+\kappa+2} N(Np)^{\ell}\frac{\prod_{i=\ell+1}^{\ell+\kappa+1}|S'_i|}{N^{\kappa+1}}

\leq \mathcal{B}_{2(\ell+1)}(N p)^{\ell-\kappa}.
\label{eq:YApositive}
\end{align}


Combining \cref{eq:YAzero,eq:YApositive}, we have
\begin{align*}
\max_{\substack{A\subseteq \binom{V}{ 2}:|A|\geq 1}}\mathbf{E}[Y_{A}]
&\leq \max_{\substack{A\subseteq \binom{V}{2}:|A|\geq 1}}\mathcal{B}_{2(\ell+1)}(Np)^{\ell-|A|}=\mathcal{B}_{2(\ell+1)}(N p)^{\ell-1}, \\
\max_{\substack{A\subseteq \binom{V}{2}}}\mathbf{E}[Y_{A}]
&=\max\left\{ \max_{\substack{A\subseteq \binom{V}{2}:|A|\geq 1}}\mathbf{E}[Y_{A}], \mathbf{E}[d_\ell(V)] \right\}
\leq \mathcal{B}_{2(\ell+1)}N(Np)^{\ell}.
\end{align*}
Thus from \cref{eq:KimVutoY}  
with $\lambda=(2(\ell-1)+C_7/2)\log N$ and $C_8=\sqrt{\ell!} \mathcal{B}_{2(\ell+1)} (16(\ell-1+C_7/2))^\ell$, 
we obtain
\begin{align}
\mathop{\mathbf{Pr}}\left[|Y-\mathbf{E}[Y]|\geq C_8\sqrt{N }(\log N)^\ell (N p)^{\ell-1/2}\right]\leq 2\mathrm{e}^2/N^{C_7}.
\label{claim:dlV}
\end{align}
Combining \cref{eq:WdlV}, \cref{claim:WEWlower} and \cref{claim:dlV}, the following holds with probability at least $1-2e^2/N^{C_7}-1/N^{C_3}$:
\begin{align*}

&\forall S_0, S_1, \ldots, S_\ell: \\
&W(S_0;S_1,\ldots,S_{\ell})
\leq
\mathbf{E}[W(S_0;S_1,\ldots,S_{\ell})]+C_9\sqrt{N }(\log N)^\ell (N p)^{\ell-1/2}+(\ell+1)C_4 N (Np)^{\ell-1/2}.
\end{align*}
Thus we obtain the claim \cref{claim:WEWupper} and combining the claims \cref{claim:WEWlower,claim:WEWupper} complete the proof of \cref{lem:WEWdiscrepancy}.

