\noindent \textbf{Lower bound.}
First we claim the following:
Two positive constants $C_3, C_4$ exist such that the following holds with probability $1-n^{-C_3}$: 
\begin{align}
&\forall A\subseteq V, \forall S_0, \ldots, S_{\ell-1}\in \mathcal{S}(A):\nonumber \\
&W(S_0;S_1,\ldots,S_{\ell-1}, A)\geq \hat{W}(S_0;S_1,\ldots,S_{\ell-1}, A)-C_4|A|\sqrt{\log n}(np)^{\ell-1/2}.
\label{claim:gomiAlower}
\end{align}
From Janson's inequality (\cref{lem:Janson}) and \cref{claim:nablaupper} with a constant $C_5$ and $C_6=\sqrt{2(C_5+1)\mathcal{B}_{2(\ell+1)}}$, we have
\begin{align}
&\mathop{\mathbf{Pr}}\left[ \substack{\exists A\subseteq V, \\ \exists S_0, \ldots, S_{\ell-1}\in \mathcal{S}(A)}: W(S_0;S_1,\ldots,S_{\ell-1}, A)\leq \mathbf{E}[W(S_0;S_1,\ldots,S_{\ell-1}, A)] -C_6|A|\sqrt{\log N}(Np)^{\ell-1/2} \right] \nonumber \\
&\leq \binom{N}{|A|} |\mathcal{S}(A)|^\ell \exp\left(-\frac{2(C_5+1)\mathcal{B}_{2(\ell+1)}|A| (\log N) (Np)^{2\ell-1}}{2\mathcal{B}_{2(\ell+1)}|A|(Np)^{2\ell-1}}\right) \nonumber  \\
& \leq 9^\ell \exp\left(|A|\log N-(C_5+1)|A|\log N\right)
\leq 9^\ell/N^{C_5}.
\label{eq:gomijan1}
\end{align}

Thus combining \cref{eq:gomijan1} and \cref{lem:EWIdiscrepancy} yields the claim \cref{claim:gomiAlower}. 





\noindent \textbf{Upper bound.}
Now we show the following claim:
Two positive constants $C_7, C_8$ exist such that the following holds with probability $1-n^{-C_7}$: 
\begin{align}
&\forall A\subseteq V, \forall S_0, \ldots, S_{\ell-1}\in \mathcal{S}(A):\nonumber \\
&W(S_0;S_1,\ldots,S_{\ell-1}, A)\leq \hat{W}(S_0;S_1,\ldots,S_{\ell-1}, A)+C_8|A|\sqrt{\log n}(np)^{\ell-1/2}.
\label{claim:gomiAupper}
\end{align}
From the same discussion of \eqref{eq:WdlV}, 
\begin{align}
W(S_0;S_1,\ldots,S_{\ell-1}, A)
&=W(\overbrace{V;V,\ldots, V}^{\ell},A)-\sum_{i=0}^{\ell-1}W(\overbrace{V;V,\ldots,V}^{i},V\setminus S_{i}, S_{i+1}, \ldots, S_{\ell-1},A)
\label{eq:gimiAsum}
\end{align}
since $W_{\ell}-W_0=\sum_{i=0}^{\ell-1}(W_{i+1}-W_{i})$.
Thus we consider an upper bound on $W(S_0;S_1,\ldots,S_{\ell-1}, A)$. 
Let $d_{\max}\mathrel{\mathop:}= \max_{v\in V}\deg(v)$.
Since $\sum_{v\in V}\deg_A(v)=\sum_{a\in A}\deg(v)$, we have
\begin{align*}
W(\overbrace{V;V,\ldots, V}^{\ell},A)
&=\sum_{v\in V}\deg(v)^{\ell-1}\deg_A(v)
\leq d_{\max}^{\ell-1}\sum_{v\in V}\deg_A(v)
\leq d_{\max}^{\ell-1}\sum_{a\in A}\deg(a)
\leq d_{\max}^{\ell}|A|.
\end{align*}
From \cref{lem:maxmindegree}, it holds with high probability that
\begin{align*}
d_{\max}^\ell
&=\left(n(p+q)+O(\sqrt{np\log n})\right)^{\ell}
=\bigl(n(p+q)\bigr)^\ell \left(1+O\left(\sqrt{\frac{\log n}{np}}\right)\right).
\end{align*}
The second equality holds since $(\log n)/(np)=o(1)$ and $\ell$ is a constant.
Hence we have

\begin{align}
W(\overbrace{V;V,\ldots, V}^{\ell},A)
&\leq 
d_{\max}^{\ell}|A|
=|A|\bigl(n(p+q)\bigr)^\ell \left(1+O\left(\sqrt{\frac{\log n}{np}}\right)\right) \nonumber \\
&\leq \hat{W}(\overbrace{V;V,\ldots, V}^{\ell},A)+O(|A|\sqrt{\log n} (np)^{\ell-1/2}).
\label{eq:gomiAlast}
\end{align}
Note that $\hat{W}(\overbrace{V;V,\ldots,V}^{\ell},A)=|A|\bigl((n-1)p+nq\bigr)^{\ell}$. 

Thus we obtain the claim \cref{claim:gomiAupper} by applying \cref{eq:gomiAlast,claim:gomiAlower} to \cref{eq:gimiAsum}.
Combining the claims \cref{claim:gomiAupper,claim:gomiAlower} complete the proof of \cref{lem:WIdiscrepancy2}.

