\sigma_{\max}=\max_{\mathbf{v}\in \mathbb{R}^n:\|\mathbf{v}\|_2=1}\|A\mathbf{v}\|_2,
\end{align*}
where the norm $\|\cdot\|_2$ is the $\ell^2$ norm.

In particular, it holds that
\begin{align*}
\|A\mathbf{v}\|_2\leq \sigma_{\max}\|\mathbf{v}\|_2
\end{align*}
for any vector $\mathbf{v}\in\mathbb{R}^n$.

 \label{def:lipschitzdef}
Consider a function $H:S\to T$, where $S\subseteq\mathbb{R}^m$ and $T\subseteq\mathbb{R}^n$ are closed sets.
The function $H$ satisfies the \emph{Lipschitz condition} if there exists a universal constant $C>0$ such that
\begin{align*}
\|H(\mathbf{x})-H(\mathbf{y})\|_\infty \leq C\|\mathbf{x}-\mathbf{y}\|_\infty
\end{align*}
holds for any $\mathbf{x},\mathbf{y}\in S$.

  \label{prop:lipschitzC1prop}
Let $O\subseteq \mathbb{R}^k$ be an open set and $S\subseteq O$ be a compact convex subset of $O$.
Suppose that $H:O\to \mathbb{R}^k$ is continuously differentiable on an open set $O$.
Then $H$ is Lipschitz continuous on $C$ and
\begin{align*}
\|H(\mathbf{x})-H(\mathbf{y})\|_\infty \leq \max_{\mathbf{p}\in S}\sigma_{\max}(J_{\mathbf{p}})\|\mathbf{x}-\mathbf{y}\|_\infty,
\end{align*}
where $J_{\mathbf{p}}$ is the Jacobian matrix at $\mathbf{p}$.

 \label{cor:lipschitzprop}
Let $H:\mathbb{R}^m\to\mathbb{R}^n$ be a function given by
\begin{align*}
H(\mathbf{x})=(H_1(\mathbf{x}),\ldots,H_n(\mathbf{x})),
\end{align*}
where $H_i(\mathbf{x})=H_i(x_1,\ldots,x_m)$ is a polynomial on $x_1,\ldots,x_m$ for all $i\in[n]$.
Then, $H$ satisfies the Lipschitz condition on $[0,1]^m$.

\label{lem:chernoff}
Let $X_1, X_2, \ldots, X_n$ be independent random variables taking values in $[0,1]$.
Let $X=\sum_{i=1}^nX_i$.
Then the following hold:
\begin{enumerate}[label=(\roman*)]
\item \label{eqn:cher1} for any $\delta\geq 0$, 
\begin{align*}
\mathop{\mathbf{Pr}}[X\geq (1+\delta)\mathbf{E}[X]] \leq \exp\left(-\frac{\min\{\delta,\delta^2\}\mathbf{E}[X]}{3}\right).
\end{align*}
\item \label{eqn:cher2} for any $\delta\in [0,1]$, 
\begin{align*}
\mathop{\mathbf{Pr}}[X\leq (1-\delta)\mathbf{E}[X]] \leq \exp\left(-\frac{\delta^2\mathbf{E}[X]}{2}\right).
\end{align*}
\item \label{eqn:cher3} for any $k\geq 2\mathrm{e}\mathbf{E}[X]$, 
\begin{align*}
\mathop{\mathbf{Pr}}\left[X\geq k \right]\leq 2^{-k}.
\end{align*}
Here, $\mathrm{e}$ denotes the Napier constant.
\end{enumerate}

