\end{align*}

\label{lem:FKG}
For a given set $[M]=\{1,2, \ldots, M\}$, let $I_1, I_2, \ldots, I_M$ be independent binary random variables.
Then for any two monotone increase functions $f,g: \{0,1\}^{M}\to \mathbb{R}$, it holds that
\begin{align*}
\mathbf{E}[f(\mathbf{I})g(\mathbf{I})]&\geq \mathbf{E}[f(\mathbf{I})]\mathbf{E}[g(\mathbf{I})]
\end{align*}
where $\mathbf{I}=(I_1, I_2, \ldots, I_M)\in \{0,1\}^{M}$.

\label{lem:Janson}
For a given set $[M]=\{1,2, \ldots, M\}$, let $I_1, I_2, \ldots, I_M$ be independent binary random variables.


Now, let $(F_1, F_2, \ldots, F_N)$ be a family of $N$ subsets of $[M]$ ($F_i\subseteq [M]$ for every $i\in [N]$) and let
\begin{align*}
Y

\mathrel{\mathop:}= \sum_{i\in [N]}\prod_{e\in F_i}I_e.
\end{align*}
Then, it holds for any $t \leq \mathbf{E}[Y]$ that
\begin{align*}
\mathop{\mathbf{Pr}}\left[Y\leq \mathbf{E}[Y]-t\right]&\leq \exp\left(-\frac{t^2}{2\nabla}\right)
\end{align*}
where
\begin{align*}
\nabla&\mathrel{\mathop:}= \sum_{\substack{i\in N, j\in N:\\F_i\cap F_j\neq \emptyset}}

\mathbf{E}\left[\left(\prod_{e\in F_i} I_e\right)\left( \prod_{e'\in F_j} I_{e'}\right)\right].
\end{align*}

\begin{align*}
\nabla&\mathrel{\mathop:}= \sum_{\substack{i\in N, j\in N:\\F_i\cap F_j\neq \emptyset}}

\mathbf{E}\left[\left(\prod_{e\in F_i} I_e\right)\left( \prod_{e'\in F_j} I_{e'}\right)\right].
\end{align*}

 \label{lem:Kim-Vu}
For a given set $[M]=\{1,2, \ldots, M\}$, let $I_1, I_2, \ldots, I_M$ be independent binary random variables.


Now, let $\mathcal{E}\subseteq 2^{[M]}$ be a collection of subsets of $[M]$ ($F\subseteq [M]$ for all $F\in \mathcal{E}$) and let
\begin{align*}
Y=\sum_{F\in \mathcal{E}}w(F)\prod_{e\in F}I_e,
\end{align*}
where $w(F)$ are positive coefficients.

For a subset $A\subseteq [M]$, define $Y_{A}$ as
\begin{align*}
Y_{A}=\sum_{\substack{F\in\mathcal{E}:\\F\supseteq A}} w(F)\prod_{e\in F\setminus A}I_e.
\end{align*}
If the polynomial $Y$ has degree at most $k$ (i.e.~$\max_{F\in\mathcal{E}}|F|\leq k$), then for any positive $\lambda>1$, it holds that
\begin{align*}
\mathop{\mathbf{Pr}}\left[|Y-\mathbf{E}[Y]|\geq \sqrt{k! \max_{A\subseteq [M]}\mathbf{E}[Y_{A}]\max_{A\subseteq [M]:A\neq \emptyset}\mathbf{E}[Y_{A}]}(8\lambda)^k\right]\leq 2\exp(2+(k-1)\log M-\lambda).
\end{align*}

 \label{thm:orbit_convergence}
Suppose that a map $T:S\to S$ satisfies the conditions \ref{cond:map_condition1} to \ref{cond:map_condition4}.
Then, for any point $\mathbf{x}\in S$, the limit $\lim_{n\to\infty}T^n(\mathbf{x})$ exists and the limit is a fixed point of $T$.

For two points $\mathbf{x}=(x_1,x_2)$ and $\mathbf{y}=(y_1,y_2)$, we write $\mathbf{x}\ll \mathbf{y}$ if $x_1<y_1$ and $x_2<y_2$.
We use the following known result:
\begin{theorem}[Theorem 5.28 of \cite{HS05}] \label{thm:competitive_map_known_result}
Suppose that a competitive map $T:S\to S$ satisfies the following:
\begin{center}
$\mathbf{x}\leq \mathbf{y}$ for any $\mathbf{x},\mathbf{y}\in S$ of $T(\mathbf{x}) \ll T(\mathbf{y})$.
\end{center}
Then,  for any $\mathbf{x}\in S$, the sequence $(T^n(\mathbf{x}))_{n\geq 0}$ converges to some fixed point of $T$
\end{theorem}

For any points $\mathbf{x},\mathbf{y}\in S$ of $T(\mathbf{x}) \ll T(\mathbf{y})$, the conditions \ref{cond:map_condition2} and \ref{cond:map_condition4} yield that $\mathbf{x}=T^{-1}(T(\mathbf{x})) \leq T^{-1}(T(\mathbf{y})) = \mathbf{y}$.
Therefore, we can directly apply \cref{thm:competitive_map_known_result}.

